// posts collection — references users by _id
{ _id: ObjectId('p001'), title: 'Intro to MongoDB', authorId: ObjectId('u001'), body: '...' }

// Two-step fetch: get post, then get its author
const post = await db.collection('posts').findOne({ _id: postId });
const author = await db.collection('users').findOne({ _id: post.authorId });
const fullPost = { ...post, author };

// Two-step fetch with batch (N posts → 1 user query instead of N)
const posts = await db.collection('posts').find({ status: 'published' }).toArray();
const authorIds = [...new Set(posts.map(p => p.authorId))];
const authors = await db.collection('users').find({ _id: { $in: authorIds } }).toArray();
const authorsMap = Object.fromEntries(authors.map(a => [a._id.toString(), a]));
const enrichedPosts = posts.map(p => ({ ...p, author: authorsMap[p.authorId.toString()] }));

// Join orders with the user who placed them
const ordersWithUsers = await db.collection('orders').aggregate([
  // Stage 1: Filter to recent orders only
  { $match: { status: 'completed', placedAt: { $gte: new Date('2026-01-01') } } },

  // Stage 2: Join with users collection
  {
    $lookup: {
      from: 'users',           // foreign collection
      localField: 'userId',    // field in orders
      foreignField: '_id',     // field in users
      as: 'user'               // output array field name
    }
  },

  // Stage 3: $lookup returns an array — $unwind converts [user] to user
  { $unwind: '$user' },

  // Stage 4: Shape the output
  {
    $project: {
      orderId: 1,
      total: 1,
      'user.name': 1,
      'user.email': 1
    }
  }
]).toArray();

// Advanced $lookup with pipeline — join products with their current discounts
const productsWithDiscounts = await db.collection('products').aggregate([
  {
    $lookup: {
      from: 'discounts',
      let: { productId: '$_id', category: '$category' },  // variables from parent
      pipeline: [
        {
          $match: {
            $expr: {
              $and: [
                { $eq: ['$productId', '$$productId'] },   // match by id
                { $gte: ['$validUntil', new Date()] }     // only active discounts
              ]
            }
          }
        },
        { $sort: { discountPct: -1 } },  // best discount first
        { $limit: 1 }                    // only the top discount
      ],
      as: 'bestDiscount'
    }
  },
  { $unwind: { path: '$bestDiscount', preserveNullAndEmptyArrays: true } }
]).toArray();

