// Simulate MongoDB $lookup in memory
const users = [
  { _id: 'u1', name: 'Alice', email: 'alice@example.com' },
  { _id: 'u2', name: 'Bob',   email: 'bob@example.com'   },
];

const posts = [
  { _id: 'p1', title: 'Intro to MongoDB', authorId: 'u1', views: 150 },
  { _id: 'p2', title: 'Schema Design Tips', authorId: 'u2', views: 89 },
  { _id: 'p3', title: 'Aggregation Deep Dive', authorId: 'u1', views: 210 },
];

// Simulate $lookup
function lookup(collection, from, localField, foreignField, as) {
  const foreignMap = {};
  from.forEach(doc => { foreignMap[doc[foreignField]] = doc; });
  return collection.map(doc => ({
    ...doc,
    [as]: foreignMap[doc[localField]] || null
  }));
}

// Join posts with their authors
const result = lookup(posts, users, 'authorId', '_id', 'author');

console.log('Posts with authors:');
result.forEach(p => {
  console.log(`"${p.title}" by ${p.author.name} — ${p.views} views`);
});

// Sort by views descending
result.sort((a, b) => b.views - a.views);
console.log('\nTop post:', result[0].title, 'by', result[0].author.name);
